// Renumbers the last migration generated by drizzle-kit when its number collides with a
// hand-written migration (see ADR-006). Usage: node scripts/renumber.mjs
import { readdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';

const dir = new URL('../migrations/', import.meta.url);
const files = readdirSync(dir).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();
const byNum = new Map();
for (const f of files) byNum.set(f.slice(0, 4), [...(byNum.get(f.slice(0, 4)) ?? []), f]);
const journalPath = new URL('meta/_journal.json', dir);
const journal = JSON.parse(readFileSync(journalPath, 'utf8'));
let max = Math.max(...files.map((f) => Number(f.slice(0, 4))));
for (const [, group] of byNum) {
  if (group.length < 2) continue;
  const generated = group.find((f) => journal.entries.some((e) => `${e.tag}.sql` === f) && f === `${journal.entries.at(-1).tag}.sql`);
  if (!generated) continue;
  max += 1;
  const renamed = `${String(max).padStart(4, '0')}${generated.slice(4)}`;
  renameSync(new URL(generated, dir), new URL(renamed, dir));
  journal.entries.at(-1).tag = renamed.replace(/\.sql$/, '');
  console.warn(`${generated} → ${renamed}`);
}
writeFileSync(journalPath, `${JSON.stringify(journal, null, 2)}\n`);
